                invArgs[j] = null;
            }
        }
        Object result = method.invoke(authenticator, invArgs);
        assertTrue("No boolean result", result instanceof Boolean);
        assertEquals("Mismatched result for " + Arrays.toString(invArgs), expected, ((Boolean) result).booleanValue());
    }
}

